import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p24_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv3d_min_softmax_cuda(torch::Tensor x, int64_t reduce_dim);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3d_min_softmax_cuda", &conv3d_min_softmax_cuda,
          "Fused min-reduction and softmax on 5D conv output (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Fused min-reduction + softmax kernel.
// Input: conv output in NCDHW layout, shape (N, C, D, H, W), contiguous float32.
// reduce_dim: the dimension to reduce over (2=D, 3=H, 4=W).
// After reducing along reduce_dim, the shape becomes (N, C, S1, S2) where
// the channel dim (1) is then softmaxed.
//
// Strategy:
//   Phase 1: each block handles one output (n, s1, s2) position.
//            Threads cooperate to find the per-channel minimum across reduce_dim.
//   Phase 2: within the same block, compute softmax over C channels.

// Kernel: one block per (n, out_i, out_j) where the two retained spatial dims
// depend on reduce_dim. blockDim.x covers C channels; each thread handles
// one channel and iterates over the reduction length.

__global__ void fused_min_softmax_kernel(
    const float* __restrict__ inp,  // (N, C, D, H, W)
    float* __restrict__ out,         // (N, C, out_i, out_j)
    int N, int C, int D, int H, int W,
    int reduce_dim,                  // 2, 3, or 4
    int reduce_len,                  // D, H, or W depending on reduce_dim
    int out_i_len,                   // length of first retained spatial dim
    int out_j_len                    // length of second retained spatial dim
) {
    // Block index encodes (n, out_i, out_j)
    int out_j = blockIdx.x % out_j_len;
    int out_i = (blockIdx.x / out_j_len) % out_i_len;
    int n     = blockIdx.x / (out_j_len * out_i_len);

    if (n >= N) return;

    int c = threadIdx.x;  // each thread handles one channel

    extern __shared__ float smem[];  // size = C floats for min values

    float my_min = FLT_MAX;

    if (c < C) {
        // Compute linear strides for input NCDHW
        // inp[n, c, d, h, w] = inp[n*C*D*H*W + c*D*H*W + d*H*W + h*W + w]
        int DHW = D * H * W;
        int HW  = H * W;

        // Depending on reduce_dim, iterate over that dimension
        if (reduce_dim == 2) {
            // reduce over D; out_i=h, out_j=w
            int h = out_i, w = out_j;
            int base = n * C * DHW + c * DHW + h * W + w;
            for (int d = 0; d < D; d++) {
                float val = inp[base + d * HW];
                if (val < my_min) my_min = val;
            }
        } else if (reduce_dim == 3) {
            // reduce over H; out_i=d, out_j=w
            int d = out_i, w = out_j;
            int base = n * C * DHW + c * DHW + d * HW + w;
            for (int h = 0; h < H; h++) {
                float val = inp[base + h * W];
                if (val < my_min) my_min = val;
            }
        } else {
            // reduce_dim == 4: reduce over W; out_i=d, out_j=h
            int d = out_i, h = out_j;
            int base = n * C * DHW + c * DHW + d * HW + h * W;
            for (int w = 0; w < W; w++) {
                float val = inp[base + w];
                if (val < my_min) my_min = val;
            }
        }
        smem[c] = my_min;
    }
    __syncthreads();

    // Now smem[0..C-1] holds per-channel minimums for this (n, out_i, out_j).
    // Compute softmax over C in shared memory.

    // Step 1: find max across C for numerical stability
    // Use a simple sequential scan by thread 0, or parallel reduction.
    // For typical C <= 512 a parallel tree reduction is fine.
    // We reuse smem for the softmax computation.

    // Parallel max reduction
    // Each thread writes its value; we reduce in-place.
    // smem already has c-th value at smem[c].
    __syncthreads();

    // Two-pass softmax using parallel reduction
    // Pass 1: max
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (c < stride && (c + stride) < C) {
            if (smem[c + stride] > smem[c]) smem[c] = smem[c + stride];
        }
        __syncthreads();
    }
    float max_val = smem[0];
    __syncthreads();

    // Restore per-channel min values for softmax
    if (c < C) smem[c] = my_min;
    __syncthreads();

    // Pass 2: compute exp(val - max) and store back
    if (c < C) smem[c] = __expf(smem[c] - max_val);
    __syncthreads();

    // Pass 3: sum reduction
    // Copy to second half of shared mem for sum
    // We need extra smem; let's use registers + second smem region.
    float my_exp = (c < C) ? smem[c] : 0.0f;
    __syncthreads();

    // Reuse smem for sum reduction
    if (c < C) smem[c] = my_exp;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (c < stride) {
            float other = ((c + stride) < C) ? smem[c + stride] : 0.0f;
            smem[c] += other;
        }
        __syncthreads();
    }
    float sum_exp = smem[0];
    __syncthreads();

    // Write normalized output
    if (c < C) {
        // out shape: (N, C, out_i_len, out_j_len)
        int out_idx = n * C * out_i_len * out_j_len
                    + c * out_i_len * out_j_len
                    + out_i * out_j_len
                    + out_j;
        out[out_idx] = my_exp / sum_exp;
    }
}

torch::Tensor conv3d_min_softmax_cuda(torch::Tensor x, int64_t reduce_dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N,C,D,H,W)");
    TORCH_CHECK(reduce_dim >= 2 && reduce_dim <= 4, "reduce_dim must be 2, 3, or 4");

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    int reduce_len, out_i_len, out_j_len;
    if (reduce_dim == 2) {
        reduce_len = D; out_i_len = H; out_j_len = W;
    } else if (reduce_dim == 3) {
        reduce_len = H; out_i_len = D; out_j_len = W;
    } else {
        reduce_len = W; out_i_len = D; out_j_len = H;
    }

    auto out = torch::empty({N, C, out_i_len, out_j_len}, x.options());

    // Round block size up to next power of 2 >= C for correct reduction
    int block_size = 1;
    while (block_size < C) block_size <<= 1;
    block_size = min(block_size, 1024);

    int total_blocks = N * out_i_len * out_j_len;
    int smem_bytes = block_size * sizeof(float);

    fused_min_softmax_kernel<<<total_blocks, block_size, smem_bytes>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        (int)reduce_dim, reduce_len, out_i_len, out_j_len
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a 3D convolution, applies minimum operation along a specific dimension, 
        and then applies softmax.
        """
    def __init__(self, in_channels, out_channels, kernel_size, dim):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, D, H, W)
                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_channels, H, W)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.conv(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = _stark_get_extension().conv3d_min_softmax_cuda(x.contiguous(), int(self.dim))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # softmax already applied by fused kernel above
        x = x
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

